PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schema_version (version INTEGER PRIMARY KEY);
CREATE TABLE saved_content (id TEXT PRIMARY KEY, payload TEXT NOT NULL, saved_at INTEGER NOT NULL);
CREATE TABLE favorite_sync (id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE downloads (id TEXT PRIMARY KEY, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE notes (id TEXT PRIMARY KEY, content_id TEXT NOT NULL, body TEXT NOT NULL, position_seconds REAL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, text_anchor TEXT, pdf_anchor TEXT, tags TEXT, pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), subtitle_references TEXT, frame TEXT);
CREATE TABLE subscriptions (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0, snapshot TEXT NOT NULL DEFAULT '');
CREATE TABLE subscription_refresh (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE read_state (content_id TEXT PRIMARY KEY, is_read INTEGER NOT NULL CHECK(is_read IN (0,1)), updated_at INTEGER NOT NULL);
CREATE TABLE reading_progress (content_id TEXT PRIMARY KEY, position_seconds REAL NOT NULL, duration_seconds REAL NOT NULL, completed INTEGER NOT NULL, revision INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE saved_subtitles (content_id TEXT NOT NULL, language TEXT NOT NULL, payload TEXT NOT NULL, revision INTEGER NOT NULL, saved_at INTEGER NOT NULL, PRIMARY KEY(content_id,language));
CREATE TABLE subscription_groups (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision > 0));
CREATE TABLE subscription_group_members (source_id TEXT PRIMARY KEY, group_id TEXT NOT NULL);
CREATE TABLE subscription_inbox (sequence INTEGER PRIMARY KEY AUTOINCREMENT, content_id TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, title TEXT NOT NULL, author TEXT NOT NULL, kind TEXT NOT NULL, first_seen_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL);
CREATE TABLE subscription_inbox_sources (content_id TEXT NOT NULL, source_id TEXT NOT NULL, source_name TEXT NOT NULL, PRIMARY KEY(content_id,source_id));
CREATE TABLE article_documents (content_id TEXT PRIMARY KEY, payload TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE subscription_feed_identity (id TEXT PRIMARY KEY, canonical TEXT NOT NULL);
CREATE TABLE recommendation_queue (
		 platform TEXT NOT NULL, account TEXT NOT NULL, content_id TEXT NOT NULL,
		 payload TEXT NOT NULL, fetched_at INTEGER NOT NULL, metadata_at INTEGER NOT NULL, seen_at INTEGER NOT NULL DEFAULT 0,
		 opened_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(platform,account,content_id));
CREATE TABLE favorite_sync_restriction (id INTEGER PRIMARY KEY CHECK(id=1), until_at INTEGER NOT NULL CHECK(until_at>=0));
CREATE TABLE note_frames (note_id TEXT PRIMARY KEY, frame_id TEXT NOT NULL, data BLOB NOT NULL CHECK(length(data)<=1048576));
CREATE TABLE note_creations (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, note_id TEXT NOT NULL);
CREATE INDEX notes_by_content ON notes(content_id, created_at DESC);
CREATE INDEX subscription_members_by_group ON subscription_group_members(group_id);
CREATE INDEX inbox_sources_by_source ON subscription_inbox_sources(source_id,content_id);
CREATE INDEX recommendation_queue_unopened ON recommendation_queue(platform,account,opened_at,seen_at,fetched_at,content_id);
COMMIT;
